/**
 * Writes small server configuration files to the output directory.
 */

import * as path from "node:path";

export async function writeRootHtaccessFile(options: {
  outputDir: string;
  writeHtaccess: boolean;
  writeIfChanged: (targetPath: string, content: string) => Promise<boolean>;
}): Promise<void> {
  const { outputDir, writeHtaccess, writeIfChanged } = options;
  if (!writeHtaccess) return;

  const htaccessPath = path.join(outputDir, ".htaccess");
  const lines = [
    "# Generated by Webette. Adjust as needed for your hosting.",
    "ErrorDocument 404 /404.html",
    "Options -Indexes",
    "# Block access to the exported model directory",
    "RedirectMatch 403 ^/_model(/|$)",
    "",
  ].join("\n");
  await writeIfChanged(htaccessPath, lines);
}

export async function writeNginxSampleFile(options: {
  outputDir: string;
  writeNginxSample: boolean;
  writeIfChanged: (targetPath: string, content: string) => Promise<boolean>;
}): Promise<void> {
  const { outputDir, writeNginxSample, writeIfChanged } = options;
  if (!writeNginxSample) return;

  const nginxPath = path.join(outputDir, "nginx.conf");
  const serverBlock = [
    "# Sample Nginx config generated by Webette.",
    "# Replace `root`/`server_name` to match your setup.",
    "server {",
    "  listen 80;",
    "  server_name _;",
    `  root ${outputDir.replace(/\\/g, "/")};`,
    "  index index.html;",
    "  error_page 404 /404.html;",
    "",
    "  location / {",
    "    try_files $uri $uri/ /404.html;",
    "  }",
    "",
    "  location /assets/ {",
    "    autoindex off;",
    "  }",
    "",
    "  location /_model/ {",
    "    return 403;",
    "  }",
    "}",
    "",
  ].join("\n");
  await writeIfChanged(nginxPath, serverBlock);
}

